<template><view class="page"><view v-if="card" class="card"><text class="progress">学习进度 {{ card.progress.completed }} / {{ card.progress.required }} 次有效回忆</text><text class="question">{{ card.question }}</text><button v-if="!showAnswer" @click="showAnswer=true">显示答案</button><view v-else><text class="answer">{{ card.answer }}</text><text v-if="card.aiSummary" class="summary">{{ card.aiSummary }}</text><view class="actions"><button @click="rate('again')">Again</button><button @click="rate('hard')">Hard</button><button @click="rate('good')">Good</button><button @click="rate('easy')">Easy</button></view></view></view><view v-else class="empty">暂无待复习卡片，明天再来看看。</view></view></template>
<script setup>
import { ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { getNextReviewCard, rateReviewCard } from '@/api/exam/review';
const card=ref(null), showAnswer=ref(false);
async function load(){card.value=(await getNextReviewCard()).data||null;showAnswer.value=false} async function rate(value){await rateReviewCard(card.value.cardId,value);await load()} onShow(()=>load().catch(()=>{}));
</script>
<style scoped>.page{min-height:100vh;background:#f5f7fb;padding:28rpx 30rpx}.card,.empty{background:#fff;border-radius:22rpx;padding:30rpx}.progress,.summary{display:block;color:#748198;font-size:22rpx;margin-bottom:22rpx}.question{display:block;color:#25324a;line-height:1.6;margin-bottom:30rpx;font-size:34rpx;font-weight:700}.answer{display:block;white-space:pre-line;line-height:1.8;font-size:25rpx;color:#344158}.summary{margin-top:24rpx;line-height:1.7}.actions{display:flex;gap:10rpx;margin-top:26rpx}.actions button{flex:1;font-size:22rpx}.empty{text-align:center;color:#8b96a8;margin-top:24rpx}</style>
